out=Path('../../outputs');out.mkdir(exist_ok=True)
r=json.loads(Path('validation/v3-final-results.json').read_text());perf=json.loads(Path('validation/performance-v3.json').read_text());flags=json.loads(Path('validation/v3-flags-results.json').read_text());summary=r['summary'];labels={'v2':'上一版默认','v3':'本版 · 忠实原图','balanced':'本版默认 · 清晰轮廓'}
photos={'astronaut':'人像','chelsea':'猫咪','coffee':'静物','camera':'黑白人物','rocket':'夜景火箭','brick':'砖墙','grass':'草地','gravel':'碎石','clock_motion':'运动模糊时钟','coins':'硬币','moon':'低对比月面','hubble_deep_field':'密集星点','motorcycle_left':'摩托车'}
def embed(im):
 b=io.BytesIO();im.save(b,format='PNG');return 'data:image/png;base64,'+base64.b64encode(b.getvalue()).decode()
